"""Stakeholder entry point, separate from the customer previews."""
from build import ROOT, head, t, a, footer


def proposal_page():
    options = [
        ('essential', '01', 'Esencial', 'Essential', 'CATÁLOGO', 'CATALOGUE',
         'Encuentra un proyecto y conversa con un asesor.', 'Find a project and speak with an advisor.',
         'Información del proyecto, tipos de vivienda y contacto. Una experiencia directa para quien busca su próximo hogar.',
         'Project information, home types and contact details. A straightforward experience for someone looking for their next home.'),
        ('editorial', '02', 'Interactivo', 'Interactive', 'PLANOS', 'PLANS',
         'Compara departamentos y conoce su distribución.', 'Compare apartments and explore their layouts.',
         'Todo lo esencial, más selección de pisos y departamentos en planos, con un diseño a medida.',
         'Everything in Essential, plus floor and apartment selection on plans, with a bespoke design.'),
        ('immersive', '03', 'Inmersivo', 'Immersive', 'ESPACIOS', 'SPACES',
         'Explora el edificio y sus espacios a tu ritmo.', 'Explore the building and its spaces at your own pace.',
         'Todo lo interactivo, más una maqueta 3D y visitas virtuales opcionales. La información siempre está a mano.',
         'Everything in Interactive, plus an optional 3D building model and virtual visits. Key information is always within reach.'),
    ]
    cards = ''
    for style, number, es, en, level, levelen, task, tasken, copy, copyen in options:
        cards += f'''<article class="option-card"><span class="overline">{number} / {t(level,levelen)}</span>{t(es,en,'h3')}{t(task,tasken,'p','option-task')}{t(copy,copyen,'p')}<a class="button" data-preview-style="{style}" href="/?style={style}">{t('Ver experiencia del cliente','Preview customer experience')} <span aria-hidden="true">↗</span></a></article>'''
    out=head('proposal')+f'''<main id="main" class="proposal-main"><section class="proposal-overview" id="resumen"><div><span class="overline">{t('EXPERIENCIAS WEB PARA INMOBILIARIAS','WEB EXPERIENCES FOR REAL ESTATE')}</span>{t('Tu proyecto.<br>Una experiencia<br>que <em>se recorre.</em>','Your project.<br>An experience<br>to <em>explore.</em>','h1')}<p>{t('Ayuda a tus compradores a imaginar su hogar: planos interactivos, espacios en 3D y consultas con el departamento que les interesa. Adaptamos la experiencia a la identidad de tu proyecto.','Help buyers picture their home: interactive plans, 3D spaces and enquiries that carry the apartment they are interested in. We adapt the experience to your project’s identity.')}</p><div class="action-row">{a('Explorar el proyecto demo','Explore the demo project','/proyecto/?style=immersive','button','data-preview-style="immersive"')}{a('Comparar experiencias','Compare experiences','/comparar/','text-link')}</div><p class="demo-disclosure">{t('Proyecto ficticio · Imágenes conceptuales generadas con IA','Fictional project · AI-generated concept imagery')}</p></div><figure><img src="/assets/pixel-living-render.png" alt="Interior conceptual de un departamento / Concept apartment interior" fetchpriority="high"><figcaption>{t('UNA MUESTRA DE LO QUE PODEMOS CREAR JUNTOS','A GLIMPSE OF WHAT WE CAN CREATE TOGETHER')}</figcaption></figure></section><section class="demo-journey"><div class="proposal-section-title"><span class="overline">{t('DE LA PRIMERA MIRADA A LA CONSULTA','FROM FIRST LOOK TO ENQUIRY')}</span>{t('Cada paso acerca<br>al comprador a su decisión.','Every step brings<br>buyers closer to a decision.','h2')}</div><div class="demo-steps"><article><span>01</span>{t('Presenta el proyecto','Present the project','h3')}{t('Arquitectura, ubicación y espacios con una identidad visual propia.','Architecture, location and spaces with a distinctive visual identity.','p')}</article><article><span>02</span>{t('Invita a explorar','Invite exploration','h3')}{t('Planos, selección de unidades y visitas visuales para entender la distribución.','Plans, unit selection and visual tours to understand the layout.','p')}</article><article><span>03</span>{t('Conecta con ventas','Connect with sales','h3')}{t('Una consulta que conserva la unidad elegida y puede integrarse con tu equipo comercial.','An enquiry that retains the selected unit and can connect to your sales team.','p')}</article></div></section><section class="proposal-next"><div>{t('UNA BASE PARA CRECER','A FOUNDATION FOR GROWTH','span','overline')}{t('Empieza por un proyecto.<br>Crece con tu portafolio.','Start with one project.<br>Grow with your portfolio.','h2')}<p>{t('Podemos trabajar con tus planos, renders y tours existentes. Definimos juntos el diseño, las integraciones y los nuevos activos que necesita el piloto.','We can work with your existing plans, renders and tours. Together we define the design, integrations and new assets the pilot needs.')}</p></div><div>{a('Hablemos de tu proyecto','Let’s talk about your project','/contacto/','button')}</div></section></main>'''+footer(True)+'</body></html>'
    (ROOT/'propuesta').mkdir(exist_ok=True)
    (ROOT/'propuesta/index.html').write_text(out)

    comparison = head('comparison') + f'''<main id="main" class="proposal-main"><section id="opciones" class="proposal-options"><div class="proposal-section-title"><span class="overline">{t('ELIGE LA EXPERIENCIA','CHOOSE THE EXPERIENCE')}</span>{t('Tres opciones.<br>Un recorrido familiar.','Three options.<br>One familiar journey.','h1')}<p>{t('En todas: conocer el proyecto, encontrar un departamento y hablar con un asesor. Abre cada opción para verla como la vería un cliente.','In every option: discover the project, find an apartment and speak with an advisor. Open each option to see it as a client would.')}</p></div><div class="option-grid">{cards}</div></section></main>''' + footer(True) + '</body></html>'
    (ROOT/'comparar').mkdir(exist_ok=True)
    (ROOT/'comparar/index.html').write_text(comparison)
